const { Queue } = require('../src/queue');

describe('Queue', () => {
  it('processes jobs in FIFO order', async () => {
    const seen = [];
    const q = new Queue({ concurrency: 1 });
    q.push(async () => seen.push('a'));
    q.push(async () => seen.push('b'));
    await q.drain();
    expect(seen).toEqual(['a', 'b']);
  });

  it('retries a failed job up to maxRetries', async () => {
    let attempts = 0;
    const q = new Queue({ concurrency: 1, maxRetries: 2 });
    q.push(async () => {
      attempts += 1;
      if (attempts < 3) throw new Error('flaky');
    });
    await q.drain();
    expect(attempts).toBe(3);
    expect(q.failed).toHaveLength(0);
  });
});

