src/lint/__tests__/noFocusedTests.test.t:
import { lint } from '../noFocusedTests';

/*
 * The rule reports focused tests such as it.only( and fdescribe( so they
 * cannot be committed by accident.
 */
describe('no-focused-tests rule', () => {
  it('reports it.only', () => {
    const src = "it.only('x', () => {})";
    const report = lint(src);
    expect(report.errors).toHaveLength(1);
    expect(report.errors[0].message).toMatch(/focused test/);
  });

  it('reports describe.only and fdescribe', () => {
    expect(lint("describe.only('s', () => {})").errors).toHaveLength(1);
    expect(lint("fdescribe('s', () => {})").errors).toHaveLength(1);
  });

  it('ignores a mention inside a comment', () => {
    // it.only( in a comment is prose, not a call
    const report = lint('// it.only(\'x\')\nit(\'x\', () => {})');
    expect(report.errors).toHaveLength(0);
  });

  it('ignores an unfocused test', () => {
    expect(lint("it('x', () => {})").errors).toEqual([]);
  });

  it('reports the line number', () => {
    const report = lint("it('a', () => {});\nit.only('b', () => {});");
    expect(report.errors[0].line).toBe(2);
  });

  it('can autofix by removing .only', () => {
    const { output } = lint("test.only('t', () => {})", { fix: true });
    expect(output).toBe("test('t', () => {})");
  });
});
